import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('chunks_csv/outlierr/2021_gas.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Function to get neighbors for a borough
def get_neighbors(borough):
    neighbors = adjacency_data[adjacency_data['borough'] == borough]['neighbor'].tolist()
    return neighbors

# Function to compute neighborhood averages
def compute_neighborhood_averages(data, borough):
    neighbors = get_neighbors(borough)
    neighborhood_values = data[data['borough'].isin(neighbors)]['Gas_value'].tolist()
    return np.mean(neighborhood_values)

# Function to account for citywide relationship
def account_for_citywide_relationship(data, borough):
    neighborhood_averages = []
    for neighbor in get_neighbors(borough):
        neighborhood_averages.append(compute_neighborhood_averages(data, neighbor))
    return np.mean(neighborhood_averages)

# Function to correct for masking bias
def correct_for_masking_bias(data, borough):
    neighborhood_values = data[data['borough'].isin(get_neighbors(borough))]['Gas_value'].tolist()
    return np.percentile(neighborhood_values, 95)

# Function to compute test statistic
def compute_test_statistic(data, borough):
    neighborhood_averages = account_for_citywide_relationship(data, borough)
    neighborhood_values = data[data['borough'].isin(get_neighbors(borough))]['Gas_value'].tolist()
    corrected_neighborhood_value = correct_for_masking_bias(data, borough)
    return (data.loc[data['borough'] == borough, 'Gas_value'].iloc[0] - corrected_neighborhood_value) / np.std(neighborhood_values)

# Main function
def main():
    data_points_used = len(data) - data[data['borough'] == 'City of London'].shape[0]
    print(f'data_points_used = {data_points_used}')

    city_of_london_value = data.loc[data['borough'] == 'City of London', 'Gas_value'].iloc[0]
    neighborhood_averages = account_for_citywide_relationship(data, 'City of London')
    corrected_neighborhood_value = correct_for_masking_bias(data, 'City of London')
    test_statistic = compute_test_statistic(data, 'City of London')

    if test_statistic > 1.96:
        print(f'FINAL ANSWER: OUTLIER - HIGH (z = {test_statistic})')
    elif test_statistic < -1.96:
        print(f'FINAL ANSWER: OUTLIER - LOW (z = {test_statistic})')
    else:
        print(f'FINAL ANSWER: NOT AN OUTLIER (z = {test_statistic})')

    print(f'z = {test_statistic}')

if __name__ == '__main__':
    main()
